import time
import os
from .connection import SshConnection
from .exceptions import ParameterException
from time import sleep as time_sleep


class cli(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.sshconn = SshConnection()

    def _get_conn(self, alias):
        if alias in self.sshconn.ssh_pool:
            return self.sshconn.ssh_pool[alias]
        else:
            raise ParameterException("alias is not exist in pool {}".format(self.sshconn.ssh_pool))

    def connect_to(self, ip, username, password, port=22, prompt="#",
                   timeout="120s", width=None, alias="default", keyfile=""):
        """
        author: jinbo.yu@nokia-sbell.com
        history change, <date>,<who>,<what and how>
        -23.07.2020,chris.l.cao@nokia-sbell.com,
                   Extend timeout from 60s to 120s
        This keyword is used to connect fhgw

        *Args:*
            - ip: ssh ip address of FHGW (mandatory)
            - username: username of ssh (mandatory)
            - password:  password of ssh (mandatory)
            - port: tcp port of ssh (optional), default is 22
            - prompt: prompt of ssh (optional), it supports regexp string, default is #
            - timeout: timeout ssh (optional), default is 60 seconds
            - width: width of ssh window (optional), default is ${None}
            - alias: alias of ssh connection (optional), default is default
            - keyfile: keyfile of ssh login (optional), default is empty
        *Command:*  None
        *Returns:*
            - connection alias, which can be used in fhgw_connection_switch
        *Example:*
        | ${alias} | connect_to | 10.56.126.63 | _nokfhgwoperator | root |
         """
        return self.sshconn.connect_to(ip, username, password, port,
                                       prompt=prompt, timeout=timeout,
                                       width=width, alias=alias,
                                       keyfile=keyfile)

    def _execute_cli(self, command, check_result=True, alias="default"):
        echo_result = self.execute("echo", alias=alias)
        cmd_result = self.execute(command, check_result=check_result, alias=alias)
        return cmd_result.replace(echo_result.strip(), "").strip()

    def _check_cmd_result(self, current, cmd):
        return_code_flag = "ret_value_code_is:"
        current.write("echo %s$?" % return_code_flag)
        raw_return_code = current.read_until_regexp(current._prompt)
        return_lines = raw_return_code.splitlines()
        return_code = 1
        for line in return_lines:
            if line.startswith(return_code_flag):
                return_code = int(line.lstrip(return_code_flag).strip())
        if return_code != 0:
            raise RuntimeError(
                "Command '%s' returned '%s' but '%s' was expected" % (cmd, return_code, "0"))

    def execute(self, command, check_result=True, alias="default", delay="0.2", silently=False):
        """
        author: jinbo.yu@nokia-sbell.com
        history change, <date>,<who>,<what and how>
        -1.2.2022,chris.l.cao@nokia-sbell.com,
                   add parameter delay
        This keyword is used to execute ssh command

        *Args:*
            - command: command(mandatory)
            - check_result: check_result (optional), if True, need check execution result
               if False, need not check execution result, default is True
            - alias: alias of ssh connection (optional), default is default
            - delay: delay before executing command (optional), default is 0.2, unit is second
        *Returns:*
            - command execution result
        *Example:*
        | ${out} | execute | command=ls -l /tmp |
         """
        fdelay = float(delay)
        _current = self._get_conn(alias)
        try:
            if not silently:
                print(_current.read())
            else:
                _current.read()
        except Exception:
            pass
        _current.write(command)
        ret = _current.read_until_regexp(_current._prompt)
        if check_result:
            time_sleep(fdelay)
            self._check_cmd_result(_current, command)
        return ret

    def download_file(self, remote_path, local_path, alias="default"):
        """
        This keyword is used to download file

        *Args:*
            - remote_path:  (mandatory)
            - local_path:  (mandatory)
            - alias: (optional), alias of ssh connection, default is default

        *Returns:*
            - None

        ``remote_path`` is a path on the remote machine. Both absolute paths
        and paths relative to the current working directory are supported.
        If the source contains wildcards explained in `glob patterns`,
        all files matching it are downloaded. In this case ``local_path``
        must always be a directory.

        ``local_path`` is the target path on the local machine. Both
        absolute paths and paths relative to the current working directory
        are supported.

        *Example:*

         ``connect_to``   1.1.1.1    username   password

         ``download_file``   /tmp/1.1   /home/ute/1.2

        The local ``local_path`` is created using the rules explained below:

        1. If the ``local_path`` is an existing file, the ``remote_path`` file
            is downloaded over it.

        2. If the ``local_path`` is an existing directory, the ``remote_path``
           file is downloaded into it. Possible file with the same name is
           overwritten.

        3. If the ``local_path`` does not exist and it ends with the path
           separator of the local operating system, it is considered a
           directory. The directory is then created and the ``remote_path``
           file is downloaded into it. Possible missing intermediate
           directories are also created.

        4. If the ``local_path`` does not exist and does not end with the
           local path separator, it is considered a file. The ``remote_path``
           missing file is downloaded and saved using that file name, and
           possible intermediate directories are also created.

        5. If ``local_path`` is not given, the current working directory on
           the local machine is used as the destination. This is typically
           the directory where the test execution was started and thus
           accessible using built-in ``${EXECDIR}`` variable.
         """
        _current = self._get_conn(alias)
        try:
            ret = _current.get_file(remote_path, local_path)
        except Exception as e:
            print(e)
            raise RuntimeError("download_file failed!")
        return ret

    def download_directory(self, source, destination='.', recursive=True, alias="default"):
        """
        author: chris.l.cao@nokia-sbell.com
        history change, <date>,<who>,<what and how>
        -2.10.2020,chris.l.cao@nokia-sbell.com,
                   Initiative version
        This keyword is used to:
        Downloads a directory, including its content, from the remote machine to
        the local machine.

        ``source`` is a path on the remote machine. Both absolute paths and
        paths relative to the current working directory are supported.

        ``destination`` is the target path on the local machine.  Both
        absolute paths and paths relative to the current working directory
        are supported.

        ``recursive`` specifies whether to recursively download all
        subdirectories inside ``source``. Subdirectories are downloaded if
        the argument value evaluates to true (see `Boolean arguments`).
        default value is True

        Examples:
        `Download Directory`  /var/logs       /tmp

        `Download Directory`  /var/logs       /tmp/non/existing

        `Download Directory`  /var/logs

        `Download Directory`  /var/logs       recursive=True

        The local ``destination`` is created as following:

        1. If ``destination`` is an existing path on the local machine,
           ``source`` directory is downloaded into it.

        2. If ``destination`` does not exist on the local machine, it is
           created and the content of ``source`` directory is downloaded
           into it.

        3. If ``destination`` is not given, ``source`` directory is
           downloaded into the current working directory on the local
           <machine. This is typically the directory where the test execution
           was started and thus accessible using the built-in ``${EXECDIR}``
           variable.
        """
        _current = self._get_conn(alias)
        try:
            ret = _current.get_directory(source, destination, recursive=recursive)
        except Exception as e:
            print(e)
            raise RuntimeError("get_directory failed!")
        return ret

    def upload_file(self, local_path, remote_path,
                    mode='744', alias="default"):
        """
        This keyword is used to upload file
        *Args:*
            - local_path: (mandatory) is the path on the local machine.
              Both absolute paths and
        paths relative to the current working directory are supported.
        If the source contains wildcards explained in `glob patterns`,
        all files matching it are uploaded. In this case ``remote_path``
        must always be a directory.
            - remote_path: (mandatory) is the target path on the remote
              machine. Both absolute paths and paths relative to the current
              working directory are supported.
            - mode: (optional) can be used to set the target file permission.
              Numeric values are accepted. The default value is ``744``
              (``-rwxr--r--``).
            - alias: (optional) alias of ssh connection, default is default

        *Returns:*
            - None

        *Example:*

        ${alias}  connect_to  1.1.1.1  username  password

        upload_file  /tmp/local.1  /home/ute/remote.2

        upload_file  /tmp/local.1  /home/ute/remote.2  777


        The remote ``remote_path`` is created as following:

        1. If ``remote_path`` is an existing file, ``local_path`` file is
           uploaded over it.

        2. If ``remote_path`` is an existing directory, ``local_path`` file is
           uploaded into it. Possible file with same name is overwritten.

        3. If ``remote_path`` does not exist and it ends with the
           `path separator`, it is considered a directory. The directory is
           then created and ``local_path`` file uploaded into it.
           Possibly missing intermediate directories are also created.

        4. If ``remote_path`` does not exist and it does not end with
           the `path separator`, it is considered a file.
           If the path to the file does not exist, it is created.

        5. If ``remote_path`` is not given, the user's home directory
           on the remote machine is used as the destination.
         """
        _current = self._get_conn(alias)
        try:
            ret = _current.put_file(local_path, remote_path, mode=mode)
        except Exception as e:
            print(e)
            raise RuntimeError("upload_file failed!")
        return ret

    def upload_directory(self, source, destination='.', mode='0744', newline='',
                         recursive=True, alias="default"):
        """
        author: chris.l.cao@nokia-sbell.com
        history change, <date>,<who>,<what and how>
        -2.10.2020,chris.l.cao@nokia-sbell.com,
                   Initiative version
        This keyword is used to:
        Uploads a directory, including its content, from the local machine to the remote machine.

        ``source`` is the path on the local machine. Both absolute paths and
        paths relative to the current working directory are supported.

        ``destination`` is the target path on the remote machine. Both
        absolute paths and paths relative to the current working directory
        are supported.

        ``mode`` can be used to set the target file permission.
        Numeric values are accepted. The default value is ``0744``
        (``-rwxr--r--``).

        ``newline`` can be used to force the line break characters that are
        written to the remote files. Valid values are ``LF`` and ``CRLF``.
        Does not work if ``scp`` is enabled.

        ``recursive`` specifies whether to recursively upload all
        subdirectories inside ``source``. Subdirectories are uploaded if the
        argument value evaluates to true (see `Boolean arguments`).
        Default value is True.

        ``scp`` enables the use of scp (secure copy protocol) for
        the file transfer. See `Transfer files with SCP` for more details.

        Examples:
        `Upload Directory`   /var/logs  /tmp

        `Upload Directory`  /var/logs  /tmp/non/existing

        `Upload Directory`  /var/logs

        `Upload Directory`  /var/logs  recursive=True

        `Upload Directory`  /var/logs  /home/groups/robot  mode=0770

        `Upload Directory`  /var/logs  newline=CRLF

        The remote ``destination`` is created as following:

        1. If ``destination`` is an existing path on the remote machine,
           ``source`` directory is uploaded into it.

        2. If ``destination`` does not exist on the remote machine, it is
           created and the content of ``source`` directory is uploaded into
           it.

        3. If ``destination`` is not given, ``source`` directory is typically
           uploaded to user's home directory on the remote machine.
        """
        _current = self._get_conn(alias)
        try:
            ret = _current.put_directory(source, destination, mode=mode, newline=newline,
                                         recursive=recursive)
        except Exception as e:
            print(e)
            raise RuntimeError("upload_file failed!")
        return ret

    def is_file(self, path, alias="default"):
        """
        Fails if the given ``path`` does NOT point to an existing file.

        *Args:*
            - path: (mandatory) is the path on the remote machine.
              Both absolute paths and
        paths relative to the current working directory are supported.
            - alias: (optional) alias of ssh connection, default is default

        *Returns:*
            - True if file exists, False if file does not exist.

        *Example:*

        ${alias}   ``connect_to``    1.1.1.1   username  password

        ${result}  ``is_file``  /home/ute/remote.2

         """
        _current = self._get_conn(alias)
        try:
            ret = _current.current.is_file(path)
        except Exception as e:
            print(e)
            raise RuntimeError("File {} does not exist.".format(path))
        return ret

    def is_dir(self, path, alias="default"):
        """
        Fails if the given ``path`` does NOT point to an existing directory.

        *Args:*
            - path: (mandatory) is the path on the remote machine.
              Both absolute paths and
        paths relative to the current working directory are supported.
            - alias: (optional) alias of ssh connection, default is default

        *Returns:*
            - True if directory exists, False if directory does not exist.

        *Example:*

        ${alias}  ``connect_to``  1.1.1.1  username  password

        ${result}  ``is_dir``  /home/ute/remote.2

         """
        _current = self._get_conn(alias)
        try:
            ret = _current.current.is_dir(path)
        except Exception as e:
            print(e)
            raise RuntimeError("Dir {} does not exist.".format(path))
        return ret

    def set_prompt(self, prompt_str, alias="default"):
        current = self._get_conn(alias)
        old_prompt = current._prompt
        current._prompt = prompt_str
        return old_prompt

    def get_prompt(self, alias="default"):
        """
        This keyword is used to get prompt
        author: chris.l.cao@nokia-sbell.com
        history change, <date>,<who>,<what and how>
        -15.09.2020,chris.l.cao@nokia-sbell.com,
                   Add prompt when alias does not exist.
        *Args:*
            - alias: alias name, default value is 'default' (optional)

        *Returns:*
            - prmpot string

        *Example:*

        ``connect_to``  10.56.126.63   _nokfhgwoperator  root   root

        ${old_prompt}  ``get_prompt``
         """
        current = self._get_conn(alias)
        return current._prompt

    def execute_bare(self, command, alias="default"):
        self._get_conn(alias).write_bare(command)

    def read_output_until(self, prompt=None, alias="default"):
        current = self._get_conn(alias)
        prompt = prompt if prompt else current._prompt
        return current.read_until_regexp(prompt)

    def disconnect(self, alias="default"):
        """
        This keyword is used to disconnect ssh connection
        author: jinbo.yu@nokia-sbell.com
        history change, <date>,<who>,<what and how>
        -09.07.2020,chris.l.cao@nokia-sbell.com,
                   Add prompt when alias does not exist.
        *Args:*
            - alias: alias name, default value is 'default' (optional)

        *Returns:*
            - None

        *Example:*

        ``connect_to``  10.56.126.63   _nokfhgwoperator  root   root

        ``disconnect``
         """
        if not alias:
            for tmp_alias in self.sshconn.ssh_pool:
                self.sshconn.ssh_pool[tmp_alias].close_connection()
            self.sshconn.ssh_pool = {}
        else:
            if alias not in self.sshconn.ssh_pool:
                print("alias:{} does not exist".format(alias))
                raise RuntimeError("This alias:{} does not exist!".format(alias))
                return
            self.sshconn.ssh_pool[alias].close_connection()
            self.sshconn.ssh_pool.pop(alias)

