    def fhgw_download_drop_file(self, drop_file_url, alias="default"):
        """
        This keyword is used to download drop file by drop file url which transfered by argument
        *Args:*
            - _drop_file_url_: drop file url (mandatory)

        *Command:*  None
        *Returns:*
            - local path of drop file after download
        *Example:*
        | ${alias_1} | fhgw_connect | 10.56.126.63 | _nokfhgwoperator | root | root |
        | fhgw_download_drop_file | https://bhisoj70.apac.nsn-net.net/artifactory/fhgw \
        -releasedbuilds/builds/FHGW20/FHGW_20.001.1.9/FHGW_SW_DROP_from_edd7e4b_to_9400efd.tar.gz |  |  |  |  |
         """
        file_name = drop_file_url.split("/")[-1]
        target_file_path = "/tmp/" + file_name
        self._execute_cli("rm -f {target_file_path}".format(target_file_path=target_file_path), alias=alias)
        self._execute_cli("cd /tmp/ && wget {drop_file_url}".format(drop_file_url=drop_file_url), alias=alias)
        return target_file_path

    def fhgw_get_sw_build(self, alias="default"):
        """
        This keyword is used to get sw build
        *Args:*

        *Command:*
            - fhgwcli swm show node / fhghcli swm show status
        *Returns:*
            - software build number such as a5f8386
        *Example:*
        | ${alias_1} | fhgw_connect | 10.56.126.63 | _nokfhgwoperator | root | root |
        | ${build} | fhgw_get_sw_build |  |  |  |  |
         """

        cmd = "/opt/nokia/bin/fhgwcli swm show node | grep build | awk '{print $5}'"
        result = self._execute_cli(cmd, alias=alias)
        if result == '' or result is None:
            cmd = "/opt/nokia/bin/fhgwcli swm show status | grep build | awk '{print $5}'"
            result = self._execute_cli(cmd, alias=alias)
        return result

