    def fhgw_list_update_info(self, local_drop_file_path, alias="default"):
        """
        This keyword is used to get update info
        *Args:*

        *Command:*
            - fhgwcli swm show update-info
        *Returns:*
            - dict object which include Field Value pair in command output
            for example, if Field have key "SW Drop Name", value should be ${result["SW Drop Name"]}
        *Example:*
        | ${alias_1} | fhgw_connect | 10.56.126.63 | _nokfhgwoperator | root | root |
        | ${update_info} | fhgw_list_basebuild | /tmp/FHGW_SW_DROP_from_edd7e4b_to_9400efd.tar.gz |  |  |  |
        """
        cmd = "/opt/nokia/bin/fhgwcli swm show update-info {} --details".format(local_drop_file_path)
        ret = self._execute_cli(cmd, alias=alias)
        lines = ret.splitlines()
        for i in range(3):
            lines.pop(0)
        lines.pop()
        current_key = ""
        result = {}
        for line in lines:
            items = line.strip().strip("|").split("|")
            if items[0].strip():
                current_key = str(items[0].strip())
                result[current_key] = str(items[1].strip())
            else:
                if isinstance(result[current_key], str):
                    result[current_key] = [result[current_key], items[1].strip()]
                else:
                    result[current_key].append(items[1].strip())
        return result

